CREATE OR REPLACE PROCEDURE "sp"(arg1 real, arg2 text, arg3 real, arg4 text)
LANGUAGE plpgsql
AS $$
DECLARE
    result_val integer := 0;
    status_text text := 'pending';
BEGIN
    IF arg1 < 0 THEN
        result_val := (arg1 * -1)::integer;
        UPDATE "chip_model"
        SET "RAM_MiB" = result_val
        WHERE "WiFi" = arg2;
    ELSIF arg1 < 10 THEN
        result_val := (arg1 + 5)::integer;
        DELETE FROM "chip_model"
        WHERE "RAM_MiB" = arg1;
    ELSIF arg1 < 20 THEN
        result_val := (arg1 * 2)::integer;
        UPDATE "screen_mode"
        SET "used_kb" = arg3 + result_val
        WHERE "Pixels" = arg4;
    ELSIF arg1 < 30 THEN
        result_val := (arg1 - 8)::integer;
        DELETE FROM "screen_mode"
        WHERE "used_kb" = arg3;
    ELSE
        result_val := (arg1 / 2)::integer;
        status_text := 'processed';
    END IF;

    UPDATE "phone" AS p
    SET "Accreditation_level" = COALESCE(p."Accreditation_level", '') || '_screen_match'
    WHERE POSITION('_screen_match' IN COALESCE(p."Accreditation_level", '')) = 0
      AND EXISTS (
          SELECT 1
          FROM "screen_mode" AS sm
          WHERE p."screen_mode" = sm."Graphics_mode"::text
            AND sm."Pixels" = arg4
            AND sm."used_kb" = arg3
      );

    UPDATE "phone" AS p
    SET "Accreditation_type" = COALESCE(p."Accreditation_type", '') || '_wifi_match'
    WHERE POSITION('_wifi_match' IN COALESCE(p."Accreditation_type", '')) = 0
      AND EXISTS (
          SELECT 1
          FROM "chip_model" AS cm
          WHERE p."chip_model" = cm."Model_name"
            AND cm."WiFi" = arg2
      );

    UPDATE "phone" AS p
    SET "Hardware_Model_name" = COALESCE(p."Hardware_Model_name", '') || '_ram_wifi_match'
    WHERE POSITION('_ram_wifi_match' IN COALESCE(p."Hardware_Model_name", '')) = 0
      AND EXISTS (
          SELECT 1
          FROM "chip_model" AS cm
          WHERE p."chip_model" = cm."Model_name"
            AND cm."RAM_MiB" = arg1
            AND cm."WiFi" = arg2
      );

    UPDATE "phone" AS p
    SET "Accreditation_type" = COALESCE(p."Accreditation_type", '') || '_dual_match'
    WHERE POSITION('_dual_match' IN COALESCE(p."Accreditation_type", '')) = 0
      AND EXISTS (
          SELECT 1
          FROM "chip_model" AS cm
          WHERE p."chip_model" = cm."Model_name"
            AND cm."WiFi" = arg2
      )
      AND EXISTS (
          SELECT 1
          FROM "screen_mode" AS sm
          WHERE p."screen_mode" = sm."Graphics_mode"::text
            AND sm."Pixels" = arg4
            AND sm."used_kb" = arg3
      );

    UPDATE "chip_model"
    SET "WiFi" = arg2 || status_text
    WHERE "RAM_MiB" = arg1;

    result_val := result_val + 3;

    UPDATE "screen_mode"
    SET "Pixels" = arg4 || '_updated'
    WHERE "used_kb" = arg3;

    DELETE FROM "chip_model"
    WHERE "RAM_MiB" > result_val;

    status_text := 'active';

    UPDATE "screen_mode"
    SET "used_kb" = arg3 + 12
    WHERE "Pixels" = arg4;

    UPDATE "chip_model"
    SET "RAM_MiB" = result_val
    WHERE "WiFi" = arg2;

    result_val := result_val - 7;

    DELETE FROM "screen_mode"
    WHERE "Pixels" = arg4 || '_old';

    UPDATE "chip_model"
    SET "WiFi" = arg2 || '_final'
    WHERE "RAM_MiB" = arg1;

    status_text := 'completed';

    UPDATE "screen_mode"
    SET "used_kb" = arg3 * 3
    WHERE "Pixels" = arg4;

    DELETE FROM "chip_model"
    WHERE "WiFi" = arg2 || status_text;
END;
$$;

